mapper.delete:
delete from chat_room
where chat_room_idx = #{roomIdx}
and (left1_yn = 'Y' and left2_yn = 'Y')

mapper.update:
update match m
set m.is_chat = 'N', m.chat_applicant = null
where 
(m.user1_idx = (
	select user1_idx from chat_room
	where chat_room_idx = #{roomIdx}
) and m.user2_idx = (
	select user2_idx from chat_room
	where chat_room_idx = #{roomIdx}
))
or
(m.user2_idx = (
	select user1_idx from chat_room
	where chat_room_idx = #{roomIdx}
) and m.user1_idx = (
	select user2_idx from chat_room
	where chat_room_idx = #{roomIdx}
))
